class AscendGemmaRMSNorm(GemmaRMSNorm):
    """Ascend-specific GemmaRMSNorm — weight_plus_one buffer removed, use runtime expression."""

    def forward_oot(self, x, residual=None):
        if residual is not None:
            residual = torch.ops.vllm.maybe_chunk_residual(x, residual)
            if enable_custom_op():
                x, _, residual = torch.ops._C_ascend.npu_add_rms_norm_bias(
                    x, residual, 1.0 + self.weight, None, self.variance_epsilon)
            else:
                x, _, residual = torch_npu.npu_add_rms_norm(
                    x, residual, 1.0 + self.weight, self.variance_epsilon)
            return x, residual
        x = DeviceOperator.npu_gemma_rms_norm(x, self.weight, self.variance_epsilon)
        return x
